enum ConvKind : uint8_t {
  CK_NONE = 0, CK_PLAIN, CK_TABLE, CK_LINEAR, CK_ENUM, CK_PAN, CK_SPECIAL
};

// A raw->display conversion table (value strings indexed by the raw value).
struct ConvTable { const char* name; uint16_t count; const char* const* values; };

// Per-knob-slot conversion descriptor.
//  kind==CK_TABLE  : display = table[clamp(raw,0,count-1)]
//  kind==CK_LINEAR : display = dispMin + (raw-rawMin)*(dispMax-dispMin)/(rawMax-rawMin)
//                    formatted to 'decimals' places + 'unit'; '+' shown if signedShow
//  kind==CK_ENUM   : display = enums split on '|', indexed (raw-rawMin)
//  kind==CK_PAN    : raw 1..127 -> L63..C..R63
//  kind==CK_PLAIN / CK_SPECIAL / CK_NONE : raw integer
struct SlotConv {
  int16_t  rawMin, rawMax;
  uint8_t  kind;        // ConvKind
  uint8_t  table;       // 1..12 when kind==CK_TABLE, else 0
  float    dispMin, dispMax;
  uint8_t  decimals;
  uint8_t  signedShow;  // show leading '+' for positive linear values
  uint8_t  varOnly;     // 1 = valid only in the Variation block (hide in
                        //     the Chorus/Insertion block); e.g. chorus mid-EQ
  const char* unit;     // linear unit suffix ("", "ms", "dB", "s", "m", "%")
  const char* enums;    // '|'-joined option list for CK_ENUM, else nullptr
  // Block-dependent range: when altRawMax > altRawMin, these REPLACE
  // rawMin/rawMax (and dispMin/dispMax) outside the Variation block.
  // Only PHASER1's STAGE uses it -- 4..12 as a Variation, 4..6 in the
  // Chorus/Insertion blocks, per the spec table and confirmed against
  // the device. Ask xgfmt::rangeFor(), never rawMin/rawMax directly.
  int16_t  altRawMin, altRawMax;
  float    altDispMin, altDispMax;
};
struct LayoutConv { SlotConv slots[16]; };

